using EscalaLivre.Domain.Scheduling;
using EscalaLivre.Application.Contracts;
using EscalaLivre.Application.Contracts.Documents;
using EscalaLivre.Application.Validation;
using System.Text.Json;
namespace EscalaLivre.Analysis.Tests;
public sealed class PublicationTests {
 public static EscalaLivreDocument Document(){using var j=JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"role-coverage-scenarios.json")));return j.RootElement.GetProperty("scenarios")[0].GetProperty("request").GetProperty("document").Deserialize<EscalaLivreDocument>(ScheduleJson.CreateOptions())!;}
 public static Publication Version(EscalaLivreDocument d)=>new(Guid.NewGuid().ToString(),1,new("2026-11-04","2026-11-04"),"2026-11-11T12:34:56.000Z",d.Company.Name,d.Company.TimeZone,d.Employees.Select(e=>new PublicationPerson(e.Id.ToString(),e.Name,e.Role)).ToArray(),d.Assignments.Select(s=>new PublicationShift(s.Id.ToString(),s.EmployeeId.ToString(),s.Role,s.Start.ToString("yyyy-MM-dd'T'HH:mm:ss"),s.End.ToString("yyyy-MM-dd'T'HH:mm:ss"),s.Break is {} b?new(b.Start.ToString("yyyy-MM-dd'T'HH:mm:ss"),b.End.ToString("yyyy-MM-dd'T'HH:mm:ss")):null)).ToArray(),[]);
 [Fact]public void SharedPreferenceCounts(){using var j=JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"publication-preference-scenarios.json")));foreach(var s in j.RootElement.GetProperty("scenarios").EnumerateArray()){var d=s.GetProperty("document").Deserialize<EscalaLivreDocument>(ScheduleJson.CreateOptions())!;var counts=PublicationPolicy.PreferenceCounts(d);Assert.Equal(s.GetProperty("expected").GetProperty("daysOff").GetInt32(),counts.DaysOff);Assert.Equal(s.GetProperty("expected").GetProperty("earlyPauses").GetInt32(),counts.EarlyPauses);}}
 [Fact]public void SharedClosureDecisions(){using var j=JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"publication-closure-scenarios.json")));foreach(var s in j.RootElement.GetProperty("scenarios").EnumerateArray()){var errors=s.GetProperty("mandatory").GetBoolean()?new[]{new ScheduleIssue("error","test","mandatory")}:Array.Empty<ScheduleIssue>();var pending=s.GetProperty("pending").EnumerateArray().Select(x=>new PublicationAcknowledgement(x.GetString()!,1,1));var ack=s.GetProperty("ack").EnumerateArray().Select(x=>x.GetString()!).ToHashSet();Assert.Equal(s.GetProperty("allowed").GetBoolean(),PublicationPolicy.ClosureError(errors,pending,ack) is null);}}
 [Fact]public void MandatoryErrorsAndAcknowledgementsAreIndependent(){Assert.NotNull(PublicationPolicy.ClosureError([new("error","test","mandatory")],[],new HashSet<string>()));Assert.NotNull(PublicationPolicy.ClosureError([],[new("staffing",1,2)],new HashSet<string>()));Assert.Null(PublicationPolicy.ClosureError([],[new("staffing",1,2)],new HashSet<string>{"staffing"}));}
 [Fact]public void SnapshotRoundtripAndCopiedCollectionsRemainIndependent(){var d=Document();var v=Version(d);Assert.True(PublicationPolicy.Valid(v));var people=v.People.ToList();d=d with{Publications=[v with{People=people}],PublicationSelections=[new(v.Period.Start,v.Period.End,v.Id)]};var mapped=ScheduleDocumentMapper.ToProjection(ScheduleDocumentMapper.ToDto(d));people.Clear();Assert.NotEmpty(mapped.Publications![0].People);Assert.Null(DocumentSafety.Error(mapped));var json=JsonSerializer.Serialize(mapped,ScheduleJson.CreateOptions());var restored=JsonSerializer.Deserialize<EscalaLivreDocument>(json,ScheduleJson.CreateOptions())!;Assert.Equal(JsonSerializer.Serialize(mapped.Publications),JsonSerializer.Serialize(restored.Publications));Assert.Equal(JsonSerializer.Serialize(mapped.PublicationSelections),JsonSerializer.Serialize(restored.PublicationSelections));}
 [Fact]public void LimitsInvalidCurrentAndCivilTimestampAreRejected(){var d=Document();var v=Version(d);Assert.False(PublicationPolicy.Valid(v with{Shifts=[v.Shifts[0] with{Start=v.Shifts[0].Start+"Z"}]}));Assert.False(PublicationPolicy.Valid(v with{Shifts=[v.Shifts[0] with{End="2026-11-08T11:30:00"}]}));Assert.NotNull(DocumentSafety.Error(d with{Publications=Enumerable.Repeat(v,11).ToArray()}));Assert.NotNull(DocumentSafety.Error(d with{Publications=[v],PublicationSelections=[new(v.Period.Start,v.Period.End,Guid.NewGuid().ToString())]}));}
}
